        best=None
        for dr in range(-max_delta,max_delta+1):
            for dc in range(-max_delta,max_delta+1):
                r0=rr+dr; c0_=c0+dc
                if r0<0 or r0+hh>H or c0_<0 or c0_+ww>W: continue
