                    key=(abs(rr-r0)+abs(c0-c0_), r0, c0_)
                else:
                    nb=sum(min(abs(r0-a)+abs(c0_-b),999) for a,b in cells)
                    # check overlap free
                    ok=True
                    for pr,pc,pbh,pbw,pcells in [(p[1:]) for p in prev]:
                        for ra in range(pbh):
                            for ca in range(pbw):
