# Careful clean implementation with verbose placement check
def f(g):
    H,W=len(g),len(g[0])
    cs=sorted(comps(g),key=lambda x:x[2])
    res=[[0]*W for _ in range(H)]
    placed=[]   # list of dicts
    for shp in cs:
        col,rr,c0,hh,ww,cells=shp
        rel=[(a-rr,b-c0) for a,b in cells]
        best=None
        # search small deltas around diagonal chain target
        for dr in range(-4,5):
            for dc in range(-4,5):
                r0=rr+dr; c0_=c0+dc
                if r0<0 or r0+hh>H or c0_<0 or c0_+ww>W: continue
                over=sum(1 for a,b in rel if (r0+a,c0_+b) in {p['cells'] for p in placed})
                nb=min(abs(r0-p['r0']) for p in placed)+min(abs(c0_-p['c0']) for p in placed) if placed else 0
                key=(over, -nb, -r0, -c0_)
                if best is None or key<best[0]: best=(key,r0,c0_)
        r0,c0_=best[1],best[2]
        placed.append({'col':col,'rel':rel,'r0':r0,'c0':c0_,'set':{(r0+a,c0_+b) for a,b in rel}})
        for a,b in rel: res[r0+a][c0_+b]=col
    return res

